from test_bufftap import test, tests
from test_nearby_invites import social, record

test('Invite tooltip explicitly sends an invitation to the other player',social+"local title,body; GameTooltip.SetText=function(_,s) title=s end; GameTooltip.AddLine=function(_,s) body=s end; BuffTap.nearbyFrame.rows[1].invite.scripts.OnEnter(); assert(title:find('Send party invite to',1,true) and body:find('send this player a party invite',1,true) and not body:find('request a party',1,true))")
test('Suggestion tooltip clearly names the leader action',social+"GetDisplayedInviteType=function() return 'SUGGEST_INVITE' end; refresh(); local title,body; GameTooltip.SetText=function(_,s) title=s end; GameTooltip.AddLine=function(_,s) body=s end; BuffTap.nearbyFrame.rows[1].invite.scripts.OnEnter(); assert(title:find('Suggest party invite',1,true) and body:find('group leader',1,true))")
test('Diagnostics viewport owns its text and leaves buttons below it',record+social+"BuffTap:Options(); local f=BuffTap.options; assert(f.diagScroll.height==314 and f.diagText.__draw.parent==f.diagContent.__draw.id and f.diagContent:GetParent()==f.diagScroll); local p=f.diagScroll.__draw.points[1]; assert(-p[3]+f.diagScroll.height==430 and f.diagScroll.shown)")
test('Long diagnostics grows only its scroll child and retains all lines',social+"BuffTap:Options(); local f=BuffTap.options; local height; f.diagContent.SetHeight=function(_,v) height=v end; f.diagText.GetStringHeight=function() return 1800 end; BuffTap.DiagnosticsLines=function() local x={}; for i=1,100 do x[i]='Diagnostic '..i end; return x end; BuffTap:Options(); assert(height==1812 and f.diagScroll.height==314 and f.diagText.text:find('Diagnostic 100',1,true))")
test('Unknown report and diagnostics switch within the same bounded area',social+"BuffTap:Options(); local f=BuffTap.options; BuffTap:ShowDiscoveryReport(); assert(f.discoveryScroll.shown and not f.diagScroll.shown and not f.diagText.shown); assert(f.discoveryScroll.height==314); f.discoveryScroll:Hide(); f.diagScroll:Show(); f.diagText:Show(); BuffTap:Options(); assert(f.diagScroll.shown and not f.discoveryScroll.shown)")
test('Debug prints nearby state and errors instead of only the last error',social+"BuffTap.nearbySetupError='test setup error'; BuffTap.nearbyCastError='test cast error'; BuffTap.nearbyLastClick='test click'; prints={}; BuffTap:Status(true); local text=table.concat(prints,' '); assert(text:find('Nearby:',1,true) and text:find('test setup error',1,true) and text:find('Nearby casting:',1,true) and text:find('test click',1,true))")
test('Disabling nearby clears stale player counts',social+"assert(BuffTap.nearbyCounts.total>0); BuffTap:ToggleNearby(); assert(BuffTap.nearbyCounts.need==0 and BuffTap.nearbyCounts.total==0)")
test('Core roster event alone updates nearby invitation state',social+"assert(not BuffTap.nearbyEvents.registered.GROUP_ROSTER_UPDATE); GetNumSubgroupMembers=function() return 4 end; BuffTap.events.scripts.OnEvent(nil,'GROUP_ROSTER_UPDATE'); advance(.2); assert(not BuffTap.nearbyFrame.rows[1].invite.shown)")
